<?php
require '../auth.php';require '../../config/koneksi.php';$allowedTypes=['Keuangan','Kegiatan','Donasi','Pembangunan'];
if($_SERVER['REQUEST_METHOD']==='POST'){$judul=trim($_POST['judul']??'');$jenis=$_POST['jenis']??'';$tanggal=$_POST['tanggal']??'';$deskripsi=trim($_POST['deskripsi']??'');$namaFile='';if($judul===''||!in_array($jenis,$allowedTypes,true)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$tanggal)){$_SESSION['error']='Data laporan belum lengkap.';}else{$file=$_FILES['file']??null;if($file&&$file['error']===UPLOAD_ERR_OK){$ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));if($file['size']>5000000||!in_array($ext,['pdf','doc','docx','jpg','jpeg','png'],true)){$_SESSION['error']='File harus PDF, DOC, DOCX, JPG, atau PNG maksimal 5 MB.';}else{$namaFile='laporan_'.time().'_'.bin2hex(random_bytes(3)).'.'.$ext;move_uploaded_file($file['tmp_name'],'../../uploads/laporan/'.$namaFile);}}if(empty($_SESSION['error'])){$createdBy=(int)$_SESSION['user_id'];$stmt=mysqli_prepare($conn,'INSERT INTO laporan (judul_laporan,jenis_laporan,tanggal,deskripsi,file,created_by) VALUES (?,?,?,?,?,?)');mysqli_stmt_bind_param($stmt,'sssssi',$judul,$jenis,$tanggal,$deskripsi,$namaFile,$createdBy);mysqli_stmt_execute($stmt);$_SESSION['success']='Laporan berhasil ditambahkan.';header('Location:index.php');exit;}}}
$page_title='Tambah Laporan';$active_menu='laporan';$admin_base='..';include '../includes/header.php';
?>
<div class="form-card"><h1>Tambah Laporan</h1><form method="POST" enctype="multipart/form-data" class="modern-form"><div class="form-group"><label>Judul</label><input name="judul" maxlength="200" required></div><div class="form-group"><label>Jenis</label><select name="jenis" required><option value="">Pilih Jenis</option><?php foreach($allowedTypes as $item):?><option><?= $item ?></option><?php endforeach;?></select></div><div class="form-group"><label>Tanggal</label><input type="date" name="tanggal" value="<?= date('Y-m-d') ?>" required></div><div class="form-group"><label>Deskripsi</label><textarea name="deskripsi" rows="7"></textarea></div><div class="form-group"><label>Lampiran (opsional, maks. 5 MB)</label><input type="file" name="file" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png"></div><button class="btn-simpan">Simpan Laporan</button> <a class="btn-kembali" href="index.php">Kembali</a></form></div>
